use super::*;

/// Top-level type names DEFINED in this module — struct / enum / type-alias / union. A leaf whose
/// signature names one is a method-in-disguise over the module's own data, not a free-standing helper.
pub(crate) fn module_defined_types(root: Node, src: &[u8]) -> std::collections::HashSet<String> {
    let mut names = std::collections::HashSet::new();
    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        if matches!(child.kind(), "struct_item" | "enum_item" | "type_item" | "union_item") {
            if let Some(n) = child.child_by_field_name("name") {
                names.insert(n.utf8_text(src).unwrap_or_default().to_string());
            }
        }
    }
    names
}
